def solve(values):
    calls = 0
    def counted(fn):
        def wrapper(*args, **kwargs):
            nonlocal calls
            calls += 1
            return fn(*args, **kwargs)
        return wrapper
    @counted
    def square(x): return x*x
    results = [square(x) for x in values]
    return {'results':results,'calls':calls}
